const body = $json.body;

// Must match the exact Persian wording used in
// rag/policies/collateral-requirements.md — the closer this query text is
// to the policy document's own vocabulary, the better Qdrant's similarity
// search finds the right excerpt.
const COLLATERAL_LABELS = {
  sayad_check: 'چک صیادی',
  salary_deduction: 'کسر از حقوق',
  investment_fund: 'صندوق سرمایه\u200cگذاری',
  gold: 'طلا',
  silver: 'نقره',
  crypto: 'رمزارز',
};

const collateralsText = (body.collaterals || [])
  .map((c) => `${COLLATERAL_LABELS[c.type] || c.type} به ارزش ${c.value} تومان`)
  .join('\u060c ') || 'بدون وثیقه';

const query = `متقاضی وام با درآمد ماهانه ${body.monthly_income} تومان، درخواست وام ${body.requested_amount} تومان برای ${body.repayment_months} ماه، وثیقه: ${collateralsText}`;

return [{ json: { query } }];

const body = $('Webhook').first().json.body;
const matches = $json.result || [];

const policyText = matches.length
  ? matches.map((m, i) => `[${i + 1}] ${m.payload.text}`).join('\n\n')
  : 'هیچ بند مشخصی از سیاست\u200cنامه پیدا نشد؛ بر اساس اصول کلی ریسک اعتباری قضاوت کن.';

// Same canonical labels as "Build Retrieval Query" — keeps the collateral
// wording the model sees consistent with the retrieved Persian policy text.
const COLLATERAL_LABELS = {
  sayad_check: 'چک صیادی',
  salary_deduction: 'کسر از حقوق',
  investment_fund: 'صندوق سرمایه\u200cگذاری',
  gold: 'طلا',
  silver: 'نقره',
  crypto: 'رمزارز',
};

const collateralsText = (body.collaterals || [])
  .map((c) => `- ${COLLATERAL_LABELS[c.type] || c.type}: ${c.value} Toman`)
  .join('\n') || 'None';

const prompt = `You are a loan risk assessment engine for a bank's pre-assessment system. Base your decision on the bank's actual policy excerpts below \u2014 do not invent rules that are not there.

Relevant policy excerpts (retrieved from the bank's policy documents):
${policyText}

Applicant monthly income (Toman): ${body.monthly_income}
Requested amount (Toman): ${body.requested_amount}
Repayment period (months): ${body.repayment_months}
Collateral offered:
${collateralsText}

Respond with ONLY a JSON object (no other text, no markdown fences) matching exactly this shape:
{"risk_score": <integer 0-100, higher is riskier>, "risk_level": "low" or "medium" or "high", "reasoning": "<2-3 sentence explanation in Persian, referencing which policy excerpt number(s) you used>", "policy_reference": "<the excerpt number(s) you used, e.g. '[1], [2]', or null if none were relevant>"}`;

return [
  {
    json: {
      model: 'llama3.2:3b',
      format: 'json',
      stream: false,
      prompt,
    },
  },
];

const webhookData = $('Webhook').first().json.body;
const aiRaw = $input.first().json.response;
const qdrantMatches = $('Search Qdrant').first().json.result || [];

let parsed;
try {
  parsed = JSON.parse(aiRaw);
} catch (e) {
  const match = String(aiRaw).match(/\{[\s\S]*\}/);
  parsed = match
    ? JSON.parse(match[0])
    : {
        risk_score: 50,
        risk_level: 'medium',
        reasoning: 'AI response could not be parsed automatically; defaulted to medium risk for manual review.',
        policy_reference: null,
      };
}

const retrievedPolicies = qdrantMatches.map((m) => ({
  text: m.payload.text,
  source: m.payload.source || null,
  score: m.score,
}));

return [
  {
    json: {
      application_id: webhookData.application_id,
      risk_score: parsed.risk_score,
      risk_level: parsed.risk_level,
      reasoning: parsed.reasoning,
      policy_reference: parsed.policy_reference ?? null,
      retrieved_policies: retrievedPolicies,
    },
  },
];
